value:
if [Parameters].[Parameter 5] = "Week" THEN

    if ([Date]) = {fixed:max([Date])} THEN TRUE
        ELSE
            if [Date] >= {fixed:max([Date])} -7 THEN 
               true
            else 
                false
            END
        END
    ELSE
    [Day Week filter (copy)_1871104940876656652]
END

